            <div class="section-header">
              <span class="section-icon">💬</span>
              <span class="section-title">本轮用户输入</span>
            </div>
            <div class="user-input-content" id="userInputContent"></div>
          </div>

          <div class="recall-section">
            <div class="section-header">
              <span class="section-icon">🔮</span>
              <span class="section-title">相关记忆召回</span>
            </div>
            <div class="memory-list" id="memoryList">
              <div class="recall-loading" id="recallLoading">正在从世界书中检索记忆</div>
            </div>
          </div>
        </div>

        <div class="panel-footer" onclick="togglePanel()">收起</div>
      </div>
