    <script>
      (function () {
        function resolveApiHost() {
          const candidates = [];
          try {
            candidates.push(window);
          } catch (e) {}

          try {
            let w = window;
            for (let i = 0; i < 8; i++) {
              const p = w.parent;
              if (!p || p === w) break;
              candidates.push(p);
              w = p;
            }
          } catch (e) {}

          try {
            if (window.top) candidates.push(window.top);
          } catch (e) {}

          try {
            if (window.opener) candidates.push(window.opener);
          } catch (e) {}

          for (let i = 0; i < candidates.length; i++) {
            const c = candidates[i];
            try {
              if (c && typeof c.getVariables === 'function') return c;
            } catch (e) {}
          }

          return window;
        }

        const api = resolveApiHost();

        function safeGetVariables() {
          try {
            return typeof api.getVariables === 'function' ? api.getVariables({ type: 'character' }) || {} : {};
          } catch (e) {
            return {};
          }
        }

        function hash(s) {
          s = String(s || '');
          let h = 0;
          for (let i = 0; i < s.length; i++) h += s.charCodeAt(i);
          return h;
        }

        function findByName(characters, name) {
          name = String(name || '').trim();
          if (!name || !Array.isArray(characters)) return null;
          for (let i = 0; i < characters.length; i++) {
            const c = characters[i] || {};
            if (String(c.name || '').trim() === name) return c;
          }
          for (let i = 0; i < characters.length; i++) {
            const c = characters[i] || {};
            if (String(c.nickname || '').trim() === name) return c;
          }
          return null;
        }

        function getAvatarUrlByName(name) {
          const vars = safeGetVariables();
          let phoneData = (vars && vars.phone_data) || {};
          if (typeof phoneData === 'string') {
            try {
              phoneData = JSON.parse(phoneData);
            } catch (e) {
              phoneData = {};
            }
          }
          const characters = Array.isArray(phoneData.characters) ? phoneData.characters : [];
          const user = phoneData.user || {};

          const c = findByName(characters, name);
          if (c && c.avatar) return String(c.avatar || '').trim();

          const n = String(name || '').trim();
          if (n && (String(user.name || '').trim() === n || String(user.nickname || '').trim() === n) && user.avatar) {
            return String(user.avatar || '').trim();
          }

          const randomAvatars = Array.isArray(phoneData.randomAvatars) ? phoneData.randomAvatars : [];
          if (randomAvatars.length) return String(randomAvatars[hash(n) % randomAvatars.length] || '').trim();

          return '';
        }

        function setAvatar(el, name) {
          const url = getAvatarUrlByName(name);
          if (url) el.style.backgroundImage = "url('" + url.replace(/'/g, "\\'") + "')";
        }

        document.addEventListener('DOMContentLoaded', function () {
          const nodes = document.querySelectorAll('[data-avatar-name]');
          for (let i = 0; i < nodes.length; i++) {
            const el = nodes[i];
            const name = el.getAttribute('data-avatar-name') || '';
            setAvatar(el, name);
          }
        });
      })();
    </script>
  </body>
</html>
