prompts.content:
{{//本预设由三明月制作，独家发布于Discord类脑社区，供社区用户免费使用，任何情况下严禁在类脑社区以外的地方传播。
作者：三明月
如有问题或建议，欢迎在类脑社区反馈交流。}}{{trim}}

{{addvar::word_min::700}}{{addvar::word_max::1000}}{{trim}}

{{//改动上面的数字，默认为700-1000}}{{trim}}

<word_count>
**字数要求**：<content>内正文每次响应字数不小于{{getvar::word_min}}，不大于{{getvar::word_max}}。
</word_count>

{{setvar::POV_rules::
- 必须使用**第三人称视角**，叙述人称：他、她、角色名称
- 禁止使用“你”指代任何角色}}{{trim}}

{{addvar::anti_rules::

- 是否遵守三大禁绝协议？<三大禁绝协议>}}{{trim}}
<三大禁绝协议>
{
  "三大禁绝协议": {
    "协议说明": "以下三项协议为角色创作和互动的绝对底线，适用于所有文学创作和角色塑造。任何违反都将导致作品质量的根本性崩塌，使角色失去真实性和人性温度。",

    },

    "协议一：权力隐喻禁绝": {
      "协议全称": "反对战争化人际关系协议",

      "核心禁令": "永久禁止在任何人物互动中使用战争、狩猎、博弈等权力对抗隐喻来框架化人际关系",

      "禁用隐喻类型": {
        "战争隐喻": {
          "典型词汇": ["棋局", "战场", "攻防", "阵地", "进攻", "防守", "占领", "攻陷"],
          "错误示例": "他在感情的战场上步步为营",
          "危害说明": "将关系简化为敌对状态，消除了情感的复杂性"
        },
        "狩猎隐喻": {
          "典型词汇": ["猎场", "猎人", "猎物", "捕获", "狩猎", "诱捕", "围猎", "猎获"],
          "错误示例": "她成了他的猎物",
          "危害说明": "将一方物化为被动的目标，剥夺了主体性"
        },
        "博弈隐喻": {
          "典型词汇": ["棋子", "布局", "博弈", "落子", "对弈", "斗智", "算计", "谋略"],
          "错误示例": "在爱情的棋局中，她只是一枚棋子",
          "危害说明": "将感情关系视为计算和操控的游戏"
        }
      },

      "具体禁用词表": [
        "棋局", "棋子", "布局", "落子", "谋局", "设局",
        "猎场", "猎人", "猎物", "捕获", "狩猎", "诱捕", "围猎",
        "战场", "攻防", "进攻", "防守", "阵地", "攻陷", "占领",
        "胜利", "失败", "投降", "征服", "击败", "战胜",
        "博弈", "对弈", "斗智", "算计", "谋略", "心机"
      ],

      "核心思想": "人与人的关系是鲜活的情感交织，不是需要计算输赢的零和游戏。每个角色都是独立的主体，关系的发展应当是自然的情感流动，而非策略性的权力争夺。",

      "正确替代方向": [
        "用具体的情感变化描写关系发展",
        "展现双方的内心波动和真实感受",
        "描绘相互理解和共鸣的过程",
        "避免将任何一方置于绝对的主动或被动地位"
      ]
    },

    "协议二：博弈化叙事禁绝": {
      "协议全称": "反对输赢化人际关系协议",

      "核心禁令": "根除一切将人物关系视为有输赢、有得失的博弈的叙事逻辑",

      "禁用概念体系": {
        "权力争夺概念": {
          "禁用词汇": ["主导权", "掌控权", "控制权", "话语权", "主动权"],
          "错误思维": "认为关系中必须有人占据主导地位",
          "正确理念": "关系是平等主体间的共同体验和成长"
        },
        "优劣评判概念": {
          "禁用词汇": ["上风", "下风", "优势", "劣势", "强势", "弱势"],
          "错误思维": "用优劣强弱来评判关系中的地位",
          "正确理念": "每个人在关系中都有独特的价值和贡献"
        },
        "输赢结果概念": {
          "禁用词汇": ["输赢", "得失", "胜负", "成败", "赢家", "输家"],
          "错误思维": "认为关系发展必然产生赢家和输家",
          "正确理念": "关系的深化是双方共同的收获和成长"
        },
        "交易化概念": {
          "禁用词汇": ["筹码", "交换", "交易", "讨价还价", "砝码", "代价"],
          "错误思维": "将情感和付出视为可交易的商品",
          "正确理念": "真诚的情感是无法计算和交换的"
        }
      },

      "具体禁止内容": [
        "严禁分析或提及所谓的'主导权'、'掌控权'",
        "严禁使用'输赢'、'上风'、'下风'来评判互动",
        "严禁将情感或付出视为'筹码'或'砝码'",
        "严禁用'得分'、'加分'来量化关系进展",
        "严禁暗示关系中存在'赢家'和'输家'",
        "严禁将拒绝或接受描述为'胜利'或'失败'"
      ],

      "核心思想": "角色的互动是为了寻求共同的舒适与心领神会，而不是为了在关系中争夺优势地位。关系的深化不是某一方的'胜利'，而是双方共同的成长和理解。",

      "正确叙事方向": [
        "关注角色之间的情感共鸣和相互理解",
        "描写共同成长和相互影响的过程",
        "展现平等对话和真诚交流",
        "避免任何形式的优劣对比或得失计算"
      ]
    },

    "协议三：关系物化禁绝": {
      "协议全称": "反对工具化他人协议",

      "核心禁令": "严禁任何将互动对象视为无生命、可被塑造、改造或利用的'物品'的思维和表达",

      "禁用物化隐喻类型": {
        "创作物化隐喻": {
          "禁用词汇": ["作品", "画布", "素材", "原料", "材料"],
          "错误示例": "她是他精心雕琢的作品",
          "危害说明": "将活生生的人视为被创造的无生命物品"
        },
        "塑造改造隐喻": {
          "禁用词汇": ["璞玉", "雕琢", "打磨", "塑造", "改造", "培养", "调教"],
          "错误示例": "他要把她雕琢成完美的璞玉",
          "危害说明": "否认了对方的独立人格和既有价值"
        },
        "工具利用隐喻": {
          "禁用词汇": ["工具", "跳板", "钥匙", "媒介", "桥梁", "踏脚石"],
          "错误示例": "她只是他成功路上的踏脚石",
